const lead = $('Validar Lead').first().json;

const respostaLLM =
  $json?.choices?.[0]?.message?.content ??
  '';

let analiseLLM;

try {
  const conteudoLimpo = String(respostaLLM)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  analiseLLM = JSON.parse(conteudoLimpo);

} catch (error) {
  analiseLLM = {
    resumo: String(respostaLLM || 'Resposta não estruturada'),
    recomendacao: 'Revisão manual recomendada',
    risco: 'nao_classificado'
  };
}

let score = 50;

if (lead.cargo) {
  score += 15;
}

if (
  String(lead.email)
    .toLowerCase()
    .endsWith('.com.br')
) {
  score += 10;
}

if (
  String(lead.empresa).length >= 5
) {
  score += 10;
}

score = Math.min(score, 100);

let classificacao = 'frio';

if (score >= 80) {
  classificacao = 'quente';
} else if (score >= 60) {
  classificacao = 'morno';
}

return {
  json: {
    nome: lead.nome,
    email: lead.email,
    empresa: lead.empresa,
    cargo: lead.cargo,
    origem: lead.origem,

    enriquecimento: {
      dominio_email: String(lead.email).split('@')[1],
      possui_cargo: Boolean(lead.cargo)
    },

    qualificacao: {
      score,
      classificacao,
      metodo: 'deterministico'
    },

    analise_llm: {
      ...analiseLLM,
      governanca: {
        modelo: 'qwen2.5-7b-instruct-1m',
        execucao: 'local',
        pii_sanitizada_antes_da_chamada: true,
        transferencia_internacional: false,
        influencia_no_score: false
      }
    },

    processado_em: new Date().toISOString()
  }
};

const nome = String($json.nome ?? '').trim();
const email = String($json.email ?? '').trim();
const empresa = String($json.empresa ?? '').trim();
const cargo = String($json.cargo ?? '').trim();
const origem = String($json.origem ?? 'n8n').trim();

if (!nome || !email || !empresa) {
  throw new Error('Campos obrigatorios: nome, email e empresa');
}

if (!email.includes('@')) {
  throw new Error('Email invalido');
}

return {
  json: {
    nome,
    email,
    empresa,
    cargo,
    origem
  }
};

return [
  {
    json: {
      nome: "Maria Silva",
      email: "maria@empresa.com.br",
      empresa: "Empresa Exemplo",
      cargo: "Gerente Comercial",
      origem: "teste-n8n"
    }
  }
];

const lead = $json;

const email = String(lead.email ?? '').trim();
const partesEmail = email.split('@');
const dominio = partesEmail.length === 2 ? partesEmail[1] : '';

return {
  json: {
    llm_input: {
      nome: '[REMOVIDO]',
      email: '[REMOVIDO]',
      dominio_email: dominio,
      empresa: String(lead.empresa ?? '').trim(),
      cargo: String(lead.cargo ?? '').trim(),
      origem: String(lead.origem ?? '').trim()
    },

    sanitizacao: {
      pii_sanitizada: true,
      campos_removidos: [
        'nome',
        'email'
      ],
      estrategia: 'supressao',
      destino: 'LLM_LOCAL',
      transferencia_internacional: false
    }
  }
};

